// 原源合同的坏身份/未来/同tick顺序门；领域payload真实性仍须原Military/Personal全验。
#include "resident/domains/growth/growth_injury_sources.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {int checks=0;void check(bool v,const char* s){++checks;if(!v)throw std::runtime_error(s);}}
int main(){try{
    CommonState seed;seed.identity.world_id[0]=1;seed.identity.tick=5;seed.next_instance_id=100;ActorRecord actor;actor.id="person";seed.actors.insert(actor.id,actor);seed.facts.insert("military:20",{"military:20","military_casualties","military"});seed.facts.insert("battle:2",{"battle:2","personal_battle","personal"});CommonStore common(seed,std::make_shared<CommonCatalog>());
    GrowthInjuryCause military{common.state().identity,"person","military:20",4,GrowthInjuryCauseKind::military_wound,1},personal{common.state().identity,"person","battle:2",4,GrowthInjuryCauseKind::personal_defeat,2};check(validate_growth_injury_cause_sequence(common,"person",{military,personal}).ok,"actual Common order not numeric instance sort");check(!validate_growth_injury_cause_sequence(common,"person",{personal,military}).ok,"reversed source order rejected");check(!validate_growth_injury_cause_sequence(common,"person",{military,military}).ok,"same injury cannot be replayed twice");auto after=apply_growth_injury_cause({0,0},military);check(after.ok&&after.value.injury==1,"military original max one");after=apply_growth_injury_cause({1,3},military);check(after.ok&&after.value.injury==1&&after.value.points==3,"military no worse grade retains original recovery points");after=apply_growth_injury_cause({1,3},personal);check(after.ok&&after.value.injury==3&&after.value.points==0,"personal original saturated addition");
    auto bad=military;bad.source_identity.revision++;check(!validate_growth_injury_cause(common,bad).ok,"other candidate revision rejected");bad=military;bad.source_fact_id="battle:2";check(!validate_growth_injury_cause(common,bad).ok,"typed military source cannot use a personal head");bad=military;bad.magnitude=2;check(!validate_growth_injury_cause(common,bad).ok,"military wound magnitude is exactly original one");bad=personal;bad.magnitude=0;check(!validate_growth_injury_cause(common,bad).ok,"zero effect must not invent injury source");bad=personal;bad.tick=6;check(!validate_growth_injury_cause(common,bad).ok,"stable source does not accept next tick");DynamicStepInput phase;phase.from_tick=5;phase.to_tick=6;check(validate_growth_injury_cause(common,bad,&phase).ok,"strict current step can observe already written cause");phase.to_tick=7;check(!validate_growth_injury_cause_sequence(common,"person",{},&phase).ok,"invalid phase rejected even with empty causes");bad=military;bad.source_fact_id="military:020";check(!validate_growth_injury_cause(common,bad).ok,"noncanonical instance rejected");check(!validate_growth_injury_cause_sequence(common,"missing",{}).ok,"empty list is not evidence of a missing person's health");
    std::cout<<"GROWTH_INJURY_SOURCES "<<checks<<" checks 0 failures\n";return 0;
}catch(const std::exception& e){std::cerr<<"GROWTH_INJURY_SOURCES "<<checks<<" checks 1 failure: "<<e.what()<<'\n';return 1;}}
